create extension if not exists pgcrypto;
create table if not exists bm_categories(id uuid primary key default gen_random_uuid(),name text not null unique,parent_id uuid references bm_categories(id));
create table if not exists bm_ingredients(id uuid primary key default gen_random_uuid(),name text not null unique,category_id uuid references bm_categories(id),parent_id uuid references bm_ingredients(id),description text);
create table if not exists bm_brands(id uuid primary key default gen_random_uuid(),name text not null unique);
create table if not exists bm_products(id uuid primary key default gen_random_uuid(),brand_id uuid references bm_brands(id),ingredient_id uuid references bm_ingredients(id),name text not null,slug text not null unique,abv numeric(5,2),country text,upc text,status text not null default 'pending' check(status in('pending','enriched','verified','review')),metadata_confidence numeric(4,3),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists bm_flavor_tags(id uuid primary key default gen_random_uuid(),name text not null unique);
create table if not exists bm_ingredient_flavors(ingredient_id uuid references bm_ingredients(id) on delete cascade,flavor_id uuid references bm_flavor_tags(id) on delete cascade,intensity numeric(4,3) not null check(intensity between 0 and 1),primary key(ingredient_id,flavor_id));
create table if not exists bm_product_flavors(product_id uuid references bm_products(id) on delete cascade,flavor_id uuid references bm_flavor_tags(id) on delete cascade,intensity numeric(4,3) not null check(intensity between 0 and 1),confidence numeric(4,3) not null default .5 check(confidence between 0 and 1),primary key(product_id,flavor_id));
create table if not exists bm_product_sources(id uuid primary key default gen_random_uuid(),product_id uuid references bm_products(id) on delete cascade,source_type text not null,source_name text,source_url text,retrieved_at timestamptz not null default now(),raw_metadata jsonb);
create table if not exists bm_user_bottles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references bm_products(id),notes text,favorite boolean not null default false,created_at timestamptz not null default now(),unique(user_id,product_id));
create table if not exists bm_drinks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,description text,created_at timestamptz not null default now());
create table if not exists bm_drink_versions(id uuid primary key default gen_random_uuid(),drink_id uuid not null references bm_drinks(id) on delete cascade,version integer not null,change_note text,tasting_note text,rating smallint check(rating between 1 and 4),is_favorite boolean not null default false,created_at timestamptz not null default now(),unique(drink_id,version));
create table if not exists bm_drink_version_ingredients(id uuid primary key default gen_random_uuid(),version_id uuid not null references bm_drink_versions(id) on delete cascade,ingredient_id uuid references bm_ingredients(id),product_id uuid references bm_products(id),amount numeric(8,3) not null,unit text not null default 'oz',sort_order integer not null default 0,check(ingredient_id is not null or product_id is not null));
create table if not exists bm_enrichment_jobs(id uuid primary key default gen_random_uuid(),product_id uuid not null references bm_products(id) on delete cascade,status text not null default 'queued' check(status in('queued','processing','review','complete','failed')),priority integer not null default 0,attempts integer not null default 0,last_error text,processed_at timestamptz,created_at timestamptz not null default now());
alter table bm_user_bottles enable row level security; alter table bm_drinks enable row level security; alter table bm_drink_versions enable row level security; alter table bm_drink_version_ingredients enable row level security;
create policy "own bottles" on bm_user_bottles for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own drinks" on bm_drinks for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own versions" on bm_drink_versions for all using(exists(select 1 from bm_drinks d where d.id=drink_id and d.user_id=auth.uid())) with check(exists(select 1 from bm_drinks d where d.id=drink_id and d.user_id=auth.uid()));
create policy "own version ingredients" on bm_drink_version_ingredients for all using(exists(select 1 from bm_drink_versions v join bm_drinks d on d.id=v.drink_id where v.id=version_id and d.user_id=auth.uid())) with check(exists(select 1 from bm_drink_versions v join bm_drinks d on d.id=v.drink_id where v.id=version_id and d.user_id=auth.uid()));